L["Known spells"] = "Bekannte Zauber"
-- en: "Manage conditions"
L["Manage conditions"] = "Bedingungen verwalten"
-- en: "Next"
L["Next"] = "Weiter"
-- en: "Page %d of %d"
L["Page %d of %d"] = "Seite %d von %d"
-- en: "Previous"
L["Previous"] = "Zurück"
-- en: "Activate profile"
L["Activate profile"] = "Profil aktivieren"
-- en: "Active profile"
L["Active profile"] = "Aktives Profil"
