L["Add return"] = "Rückgabewert hinzufügen"
-- en: "Built-in function"
L["Built-in function"] = "Integrierte Funktion"
-- en: "Custom function"
L["Custom function"] = "Benutzerdefinierte Funktion"
-- en: "Delete this function? Existing dependents will become unavailable."
L["Delete this function? Existing dependents will become unavailable."] = "Diese Funktion löschen? Bestehende abhängige Elemente werden nicht mehr verfügbar sein."
-- en: "Deletion staged. Apply to remove this function."
L["Deletion staged. Apply to remove this function."] = "Löschen vorgemerkt. Übernehmen, um diese Funktion zu entfernen."
