-- en: "Ownership required"
L["Ownership required"] = "Besitzer erforderlich"
-- en: "These records have no assigned owner. Choose Class or This character explicitly. No ownership is inferred from names, spells or profile history."
L["These records have no assigned owner. Choose Class or This character explicitly. No ownership is inferred from names, spells or profile history."] = "Diese Einträge haben keinen zugewiesenen Besitzer. Ausdrücklich „Klasse“ oder „Dieser Charakter“ wählen. Es wird kein Besitzer aus Namen, Zaubern oder dem Profilverlauf abgeleitet."
-- en: "Recovery unavailable: %s"
L["Recovery unavailable: %s"] = "Wiederherstellung nicht verfügbar: %s"
